const test=require('node:test');
const assert=require('node:assert/strict');
const {parseFields}=require('../fields.cjs');
test('quoted separators, comments and empty values',()=>{
  assert.deepEqual({...parseFields('actor=Li note="a # b" empty= path="C:\\\\logs" # ignored=x')},
    {actor:'Li',note:'a # b',empty:'',path:'C:\\logs'});
  assert.deepEqual({...parseFields('a="say \\"yes\\"" b=x=y')},{a:'say "yes"',b:'x=y'});
  assert.deepEqual({...parseFields('a=ok# comment')},{a:'ok'});
  assert.deepEqual({...parseFields(' \t# ignored')},{});
  const result=parseFields('__proto__=safe constructor=value');
  assert.equal(Object.hasOwn(result,'__proto__'),true);
  assert.equal(result.__proto__,'safe');
  assert.equal(result.constructor,'value');
});
test('reject malformed data',()=>{
  for(const line of ['a=1 a=2','a','1a=x','a="unfinished','a="x"tail','a="bad\\q"','a=bad\\path','a=x\nb=y','a=x\r','a=ab"cd']) {
    assert.throws(()=>parseFields(line),SyntaxError,line);
  }
});

