exports.parseFields=function(line) {
  if(/[\r\n]/.test(line)) throw new SyntaxError('physical line required');
  const result=Object.create(null);
  let i=0;
  const space=c=>c===' '||c==='\t';
  while(i<line.length) {
    while(space(line[i])) i++;
    if(i===line.length||line[i]==='#') break;
    const key=/^[A-Za-z_][A-Za-z0-9_]*/.exec(line.slice(i));
    if(!key) throw new SyntaxError('invalid key');
    i+=key[0].length;
    if(line[i++]!=='=' || Object.hasOwn(result,key[0])) throw new SyntaxError('missing equals or duplicate key');
    let value='';
    if(line[i]==='"') {
      i++;
      let closed=false;
      while(i<line.length) {
        let c=line[i++];
        if(c==='"') {closed=true;break;}
        if(c==='\\') {
          c=line[i++];
          if(c!=='"' && c!=='\\') throw new SyntaxError('invalid escape');
        }
        value+=c;
      }
      if(!closed || (i<line.length && !space(line[i]) && line[i]!=='#')) throw new SyntaxError('invalid quoted field');
    } else {
      while(i<line.length && !space(line[i]) && line[i]!=='#') {
        const c=line[i++];
        if(c==='"'||c==='\\') throw new SyntaxError('invalid unquoted character');
        value+=c;
      }
    }
    result[key[0]]=value;
  }
  return result;
};

